// Import pages
import Login from "pages/auth/Login";
import Register from "pages/auth/Register";
import Dashboard from "pages/admin/Dashboard"; // Example admin page
import Settings from "pages/admin/Settings"; // Another example admin page
import Profile from "pages/admin/Profile"; // Another example admin page

// Define routes for the Auth layout
export const AuthRoutes = [
  {
    path: "login",
    name: "Login",
    component: <Login />,
    layout: "/auth"
  },
  {
    path: "register",
    name: "Register",
    component: <Register />,
    layout: "/auth"
  }
];

// Define routes for the Admin layout
export const AdminRoutes = [
  {
    path: "dashboard",
    name: "Dashboard",
    component: <Dashboard />,
    layout: "/admin"
  },
  {
    path: "settings",
    name: "Settings",
    component: <Settings />,
    layout: "/admin"
  },
  {
    path: "profile",
    name: "Profile",
    component: <Profile />,
    layout: "/admin"
  }
];

// Export all routes for use in layout components
const routes = [
  ...AuthRoutes,
  ...AdminRoutes
];

export default routes;
